/*
 * test_reference.c — regression test against the ppigrf reference
 * datasets in tests/reference/.
 *
 * The datasets were generated by tools/generate_reference.py with the
 * ppigrf (IAGA-VMOD) reference implementation on the validation grid
 * required by the specification.  A row passes when the difference is
 * within IGRF_REF_ABS_TOL nT OR IGRF_REF_REL_TOL relative; the test
 * reports the maximum absolute and maximum relative error over all
 * rows and components.
 */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "igrf.h"
#include "testutil.h"

/* Accept a value when the absolute error is below this [nT] ... */
#define IGRF_REF_ABS_TOL 1e-4
/* ... or the relative error is below this. */
#define IGRF_REF_REL_TOL 1e-9

static int parse_csv_row(char *line, double *v, int n)
{
    int i;

    for (i = 0; i < n; i++) {
        char *tok = strtok(i == 0 ? line : NULL, ",");

        if (tok == NULL) {
            return -1;
        }
        v[i] = strtod(tok, NULL);
    }
    return 0;
}

static int check_file(const char *path, const char *model_name,
                      int geodetic, long *rows,
                      double *max_abs, double *max_rel)
{
    FILE *fp = fopen(path, "r");
    char line[512];
    igrf_model_t *model;
    long good = 0;
    double worst_abs = 0.0, worst_rel = 0.0;

    if (fp == NULL) {
        printf("FAIL test_reference: cannot open %s\n", path);
        tt_failures++;
        return -1;
    }
    model = igrf_model_load(model_name);
    if (model == NULL) {
        printf("FAIL test_reference: cannot load %s\n", model_name);
        tt_failures++;
        fclose(fp);
        return -1;
    }

    while (fgets(line, sizeof(line), fp) != NULL) {
        double v[7];
        double ref[3];
        double got[3];
        int k;

        if (line[0] == '#' || line[0] == '\0' || line[0] == '\n' ||
            line[0] == '\r') {
            continue;
        }
        if (parse_csv_row(line, v, 7) != 0) {
            printf("FAIL test_reference: malformed row in %s: %s\n", path,
                   line);
            tt_failures++;
            continue;
        }

        if (geodetic) {
            igrf_geodetic_t p;
            igrf_ned_t b;

            p.lon_deg = v[1];
            p.lat_deg = v[2];
            p.height_km = v[3];
            if (igrf_compute_geodetic(model, v[0], &p, &b) != IGRF_OK) {
                printf("FAIL test_reference: compute failed for %s\n",
                       line);
                tt_failures++;
                continue;
            }
            got[0] = b.X_nT;
            got[1] = b.Y_nT;
            got[2] = b.Z_nT;
        } else {
            igrf_geocentric_t p;
            igrf_spherical_t b;

            p.r_km = v[1];
            p.theta_deg = v[2];
            p.phi_deg = v[3];
            if (igrf_compute_geocentric(model, v[0], &p, &b) != IGRF_OK) {
                printf("FAIL test_reference: compute failed for %s\n",
                       line);
                tt_failures++;
                continue;
            }
            got[0] = b.Br_nT;
            got[1] = b.Btheta_nT;
            got[2] = b.Bphi_nT;
        }
        ref[0] = v[4];
        ref[1] = v[5];
        ref[2] = v[6];

        tt_checks++;
        for (k = 0; k < 3; k++) {
            double abs_err = fabs(got[k] - ref[k]);
            double rel_err = abs_err / (fabs(ref[k]) > 0.0
                                            ? fabs(ref[k])
                                            : 1.0);

            if (abs_err > worst_abs) {
                worst_abs = abs_err;
            }
            if (rel_err > worst_rel) {
                worst_rel = rel_err;
            }
            if (!(abs_err <= IGRF_REF_ABS_TOL ||
                  rel_err <= IGRF_REF_REL_TOL)) {
                tt_failures++;
                printf("FAIL test_reference: %s row [%.8g %.8g %.8g %.8g] "
                       "component %d: got %.10g, ref %.10g "
                       "(abs %.3g, rel %.3g)\n",
                       path, v[0], v[1], v[2], v[3], k, got[k], ref[k],
                       abs_err, rel_err);
            }
        }
        good++;
    }

    igrf_model_free(model);
    fclose(fp);
    *rows = good;
    *max_abs = worst_abs;
    *max_rel = worst_rel;
    return good > 0 ? 0 : -1;
}

int main(void)
{
    long rows = 0;
    double max_abs = 0.0, max_rel = 0.0;
    struct {
        const char *csv;
        const char *model;
        int geodetic;
    } files[] = {
        { IGRF_TEST_REFERENCE_DIR "/igrf14_geodetic.csv",
          IGRF_TEST_DATA_DIR "/igrf14.shc", 1 },
        { IGRF_TEST_REFERENCE_DIR "/igrf14_geocentric.csv",
          IGRF_TEST_DATA_DIR "/igrf14.shc", 0 },
        { IGRF_TEST_REFERENCE_DIR "/igrf13_geodetic.csv",
          IGRF_TEST_DATA_DIR "/igrf13.shc", 1 },
        { IGRF_TEST_REFERENCE_DIR "/igrf13_geocentric.csv",
          IGRF_TEST_DATA_DIR "/igrf13.shc", 0 },
    };
    size_t i;

    for (i = 0; i < sizeof(files) / sizeof(files[0]); i++) {
        long n = 0;
        double a = 0.0, r = 0.0;

        if (check_file(files[i].csv, files[i].model, files[i].geodetic,
                       &n, &a, &r) == 0) {
            printf("  %-28s %5ld rows  max abs err = %.3g nT  "
                   "max rel err = %.3g\n",
                   files[i].csv + strlen(IGRF_TEST_REFERENCE_DIR),
                   n, a, r);
        }
        if (n > 0) {
            rows += n;
        }
        if (a > max_abs) {
            max_abs = a;
        }
        if (r > max_rel) {
            max_rel = r;
        }
    }

    CHECK(rows > 0, "reference datasets must contain rows");
    printf("  total %ld rows: max abs err = %.3g nT (tol %.0e), "
           "max rel err = %.3g (tol %.0e)\n",
           rows, max_abs, (double)IGRF_REF_ABS_TOL, max_rel,
           (double)IGRF_REF_REL_TOL);

    return tt_report("test_reference");
}
